 static Dictionary<string,object> Probe(int id){try{var p=Process.GetProcessById(id);var handle=p.Handle;string command=null;int parent=0;using(var q=new ManagementObjectSearcher("SELECT CommandLine,ParentProcessId FROM Win32_Process WHERE ProcessId="+id)){foreach(ManagementObject v in q.Get()){command=Convert.ToString(v["CommandLine"]);parent=Convert.ToInt32(v["ParentProcessId"]);}}return new Dictionary<string,object>{{"state","alive"},{"pid",id},{"createdAtMs",new DateTimeOffset(p.StartTime.ToUniversalTime()).ToUnixTimeMilliseconds()},{"startedAt",p.StartTime.ToUniversalTime().ToString("o")},{"exe",p.MainModule.FileName},{"commandLine",command},{"parentPid",parent},{"sessionId",p.SessionId}};}catch(ArgumentException){return new Dictionary<string,object>{{"state","dead"}};}catch{return new Dictionary<string,object>{{"state","unknown"}};}}
