 static void Server(){Stage="host-parent";var policy=Input(Console.In,20000);var main=Alive((int)Num(policy,"mainPid"));if(Num(Alive(Process.GetCurrentProcess().Id),"parentPid")!=Num(main,"pid")||!Same(Str(main,"exe"),Str(policy,"mainExe")))throw Fail("MCP_HOST_IDENTITY");MainScript(main);var host=Obj(Get(policy,"hostInstance"));if(Num(main,"createdAtMs")!=Num(host,"createdAtMs")||Hash(Regular(Str(main,"exe"),536870912))!=Str(host,"exeSha256"))throw Fail("MCP_HOST_IDENTITY");Watch((int)Num(main,"pid"),Num(main,"createdAtMs"));string name=Str(policy,"pipeName"),id=Str(policy,"invitationId");Guid parsedId;if(name!="aicg-c3-"+id||!Guid.TryParse(id,out parsedId))throw Fail("MCP_PIPE_POLICY");Stage="pipe-create";var acl=new PipeSecurity();acl.SetAccessRuleProtection(true,false);acl.AddAccessRule(new PipeAccessRule(WindowsIdentity.GetCurrent().User,PipeAccessRights.FullControl,AccessControlType.Allow));using(var pipe=CreateServer(name,acl)){Emit(new{type="ready",serverPid=Process.GetCurrentProcess().Id});pipe.WaitForConnection();uint pid;if(!GetNamedPipeClientProcessId(pipe.SafePipeHandle,out pid))throw Fail("MCP_PEER_IDENTITY");Stage="owned-pipe-client";var client=Alive((int)pid);if(!Same(Str(client,"exe"),Own)||Hash(Regular(Own,16777216))!=Hash(Regular(Str(client,"exe"),16777216)))throw Fail("MCP_PEER_IDENTITY");var adapter=Alive((int)Num(client,"parentPid"));Script(adapter,"desktop/mcp/external-adapter.cjs",id);var front=Alive((int)Num(adapter,"parentPid"));var fa=Args(Str(front,"commandLine"));if(fa.Length!=3)throw Fail("MCP_PEER_IDENTITY");Script(front,"tools/connect-native-codex.cjs",fa[2]);var bridge=Alive((int)Num(front,"parentPid"));if(!Same(Str(bridge,"exe"),Own))throw Fail("MCP_PEER_IDENTITY");var ca=Args(Str(bridge,"commandLine"));if(ca.Length!=4||ca[1]!="--stdio"||ca[2]!="--connection"||ca[3]!=fa[2])throw Fail("MCP_CONNECTION_REQUIRED");Watch((int)Num(bridge,"pid"),Num(bridge,"createdAtMs"));var reader=new StreamReader(pipe,new UTF8Encoding(false,true),false,4096,true);var writer=new StreamWriter(pipe,new UTF8Encoding(false),4096,true){AutoFlush=true};var nonce=new byte[32];using(var rng=RandomNumberGenerator.Create())rng.GetBytes(nonce);string challenge=Convert.ToBase64String(nonce);writer.WriteLine(Json.Serialize(new{type="challenge",nonce=challenge}));Stage="connection-proof";var auth=Input(reader,4096);string connectionId=Str(auth,"id");if(connectionId!=ca[3])throw Fail("MCP_CONNECTION_REQUIRED");var e=Connection(Str(policy,"registryFile"),connectionId);long rev=Num(e,"revision");if(Num(auth,"revision")!=rev||!Equal(Str(auth,"proof"),Proof(Key(Str(policy,"credentialDirectory"),connectionId),connectionId,rev,challenge,(int)pid)))throw Fail("MCP_CONNECTION_PROOF");Emit(new{type="peer",newOpenIntent=true,clientTransport="native-stdio",adapterPid=(int)Num(adapter,"pid"),clientPid=(int)Num(front,"pid"),clientCreatedAtMs=Num(front,"createdAtMs"),clientSha256=Str(policy,"clientSha256"),testMode=false,registrationId=connectionId,registrationRevision=rev,agentPid=(int)Num(bridge,"pid"),agentCreatedAtMs=Num(bridge,"createdAtMs"),agentSha256="capability/1"});if(Str(Input(Console.In,1000),"type")!="accept")throw Fail("MCP_PEER_IDENTITY");writer.WriteLine("{\"type\":\"connected\"}");while(pipe.IsConnected){var line=Line(reader,MaxFrame);if(line==null)break;var q=Obj(Json.DeserializeObject(line));if(Str(q,"type")!="query"||Num(q,"seq")<1)throw Fail("MCP_PIPE_FRAME");Emit(q);string response=Line(Console.In,MaxFrame);if(response==null)break;writer.WriteLine(response);}Emit(new{type="disconnected"});}}
 static void Client(string id,string registry,string connectionId){var cfg=Read(Path.Combine(Root,"integration-build.json"),1048576);string file=Path.Combine(Str(cfg,"runtimeRoot"),"external-sessions",id+".json");var v=Read(file,8000);if(Str(v,"invitationId")!=id||Str(v,"pipeName")!="aicg-c3-"+id)throw Fail("MCP_INVITATION");AssertAuthority(v);using(var pipe=new NamedPipeClientStream(".",Str(v,"pipeName"),PipeDirection.InOut,PipeOptions.None,TokenImpersonationLevel.Identification)){pipe.Connect(5000);uint pid;if(!GetNamedPipeServerProcessId(pipe.SafePipeHandle,out pid)||pid!=Num(v,"serverPid"))throw Fail("MCP_SERVER_IDENTITY");var server=Alive((int)pid);if(!Same(Str(server,"exe"),Trusted("tools/AICG-MCP.exe")))throw Fail("MCP_SERVER_IDENTITY");var main=Alive((int)Num(server,"parentPid"));MainScript(main);var host=Obj(Get(v,"hostInstance"));if(Num(main,"pid")!=Num(v,"mainPid")||Num(main,"createdAtMs")!=Num(host,"createdAtMs")||Hash(Regular(Str(main,"exe"),536870912))!=Str(host,"exeSha256"))throw Fail("MCP_HOST_IDENTITY");Watch((int)pid,Num(server,"createdAtMs"));var reader=new StreamReader(pipe,new UTF8Encoding(false,true),false,4096,true);var writer=new StreamWriter(pipe,new UTF8Encoding(false),4096,true){AutoFlush=true};var challenge=Input(reader,1000);if(Str(challenge,"type")!="challenge")throw Fail("MCP_SERVER_IDENTITY");var e=Connection(registry,connectionId);long rev=Num(e,"revision");writer.WriteLine(Json.Serialize(new{id=connectionId,revision=rev,proof=Proof(Key(Path.Combine(Path.GetDirectoryName(registry),"mcp-credentials"),connectionId),connectionId,rev,Str(challenge,"nonce"),Process.GetCurrentProcess().Id)}));var hello=Input(reader,1000);if(Str(hello,"type")!="connected")throw Fail("MCP_SERVER_IDENTITY");Emit(hello);string line;while((line=Line(Console.In,MaxFrame))!=null){writer.WriteLine(line);line=Line(reader,MaxFrame);if(line==null)break;Console.Out.WriteLine(line);Console.Out.Flush();}}}
