 static void Pump(Stream source,Stream destination){var buffer=new byte[8192];int count;while((count=source.Read(buffer,0,buffer.Length))>0){destination.Write(buffer,0,count);destination.Flush();}}
 static int RunJs(string rel,string[] args,bool stdio){Trusted("tools/AICG-MCP.exe");var info=new ProcessStartInfo(Trusted("tools/electron/electron.exe"),Quote(Trusted(rel)));foreach(var a in args)info.Arguments+=" "+Quote(a);info.UseShellExecute=false;info.CreateNoWindow=true;info.WorkingDirectory=Root;info.RedirectStandardInput=true;info.RedirectStandardOutput=true;info.RedirectStandardError=true;info.EnvironmentVariables.Clear();foreach(string key in new[]{"SystemRoot","WINDIR","TEMP","TMP","USERPROFILE","LOCALAPPDATA","APPDATA","PATH"}){var v=Environment.GetEnvironmentVariable(key);if(v!=null)info.EnvironmentVariables[key]=v;}info.EnvironmentVariables["ELECTRON_RUN_AS_NODE"]="1";if(stdio)info.EnvironmentVariables["AICG_MCP_CONNECTION_ID"]=args[0];using(var p=Process.Start(info)){Task.Run(delegate{try{Pump(Console.OpenStandardInput(),p.StandardInput.BaseStream);}catch{}finally{try{p.StandardInput.Close();}catch{}}});var err=Task.Run(delegate{Pump(p.StandardError.BaseStream,Console.OpenStandardError());});Pump(p.StandardOutput.BaseStream,Console.OpenStandardOutput());p.WaitForExit();err.Wait();return p.ExitCode;}}
 public static int Main(string[] a){Console.InputEncoding=new UTF8Encoding(false,true);Console.OutputEncoding=new UTF8Encoding(false);try{if(a.Length==2&&a[0]=="--probe"){Emit(Probe(Int32.Parse(a[1])));return 0;}if(a.Length==1&&a[0]=="--host"){Trusted("tools/AICG-MCP.exe");Server();return 0;}if(a.Length==4&&a[0]=="--client"){Trusted("tools/AICG-MCP.exe");Client(a[1],a[2],a[3]);return 0;}if(a.Length==3&&a[0]=="--stdio"&&a[1]=="--connection"){return RunJs("tools/connect-native-codex.cjs",new[]{a[2]},true);}if(a.Length>=1&&a[0]=="--manage"){var rest=new string[a.Length-1];Array.Copy(a,1,rest,0,rest.Length);return RunJs("tools/mcp-connections.cjs",rest,false);}if(a.Length==2&&a[0]=="--create-key"){string f=Path.GetFullPath(a[1]);if(File.Exists(f))throw Fail("MCP_CONNECTION_EXISTS");Directory.CreateDirectory(Path.GetDirectoryName(f));var bytes=new byte[32];using(var rng=RandomNumberGenerator.Create())rng.GetBytes(bytes);var encrypted=ProtectedData.Protect(bytes,Encoding.UTF8.GetBytes("AICG MCP connection/1"),DataProtectionScope.CurrentUser);var acl=new FileSecurity();acl.SetAccessRuleProtection(true,false);acl.AddAccessRule(new FileSystemAccessRule(WindowsIdentity.GetCurrent().User,FileSystemRights.FullControl,AccessControlType.Allow));using(var s=new FileStream(f,FileMode.CreateNew,FileSystemRights.Write,FileShare.None,4096,FileOptions.WriteThrough,acl)){s.Write(encrypted,0,encrypted.Length);s.Flush(true);}Emit(new{created=true});return 0;}throw Fail("MCP_BRIDGE_ARGUMENTS");}catch(Exception e){string code=System.Text.RegularExpressions.Regex.IsMatch(e.Message??"","^MCP_[A-Z_]{1,60}$")?e.Message:"MCP_BRIDGE_FAILED";Emit(new{type="rejected",code=code,stage=Stage});return 2;}}
